import{_ as i,o as a,c as t,ai as n}from"./chunks/framework.Ba-VnP44.js";const g=JSON.parse('{"title":"对外 API 设计与开放平台","description":"","frontmatter":{},"headers":[],"relativePath":"apps/integration/open-api.md","filePath":"apps/integration/open-api.md"}'),e={name:"apps/integration/open-api.md"};function p(l,s,r,h,d,k){return a(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="对外-api-设计与开放平台" tabindex="-1">对外 API 设计与开放平台 <a class="header-anchor" href="#对外-api-设计与开放平台" aria-label="Permalink to “对外 API 设计与开放平台”">​</a></h1><h2 id="背景与问题" tabindex="-1">背景与问题 <a class="header-anchor" href="#背景与问题" aria-label="Permalink to “背景与问题”">​</a></h2><p>给第三方开 API，和内部接口完全是两回事。内部接口可以口头约定、跟着发版一起改；对外接口一旦发布，就会有几十个你没见过的团队在调，改错了人家的生产直接挂。</p><p>常见踩过的坑：</p><ul><li><strong>接口规范不统一</strong>：有的接口返回 <code>{&quot;code&quot;:0}</code>，有的返回 <code>{&quot;success&quot;:true}</code>，第三方对接时骂娘；</li><li><strong>鉴权各自为政</strong>：一个系统一套签名算法，甚至明文 AppKey 满天飞；</li><li><strong>没有限流</strong>：某个客户写了个死循环，把网关打满，所有客户一起遭殃；</li><li><strong>没有版本管理</strong>：字段说加就加、说删就删，老客户升级要挨个打电话通知；</li><li><strong>文档靠嘴</strong>：联调时全靠拉群问，问一次答一次，人一走就没人答了。</li></ul><p>开放平台本质上是把「接口」当产品来做：规范、鉴权、配额、版本、文档，缺一个都会在客户变多之后爆出来。</p><h2 id="方案设计" tabindex="-1">方案设计 <a class="header-anchor" href="#方案设计" aria-label="Permalink to “方案设计”">​</a></h2><p>整体分四层：</p><ol><li><strong>接入层（网关）</strong>：统一鉴权、限流、日志、路由，业务代码不写这些；</li><li><strong>接口层</strong>：统一响应结构、统一错误码、统一入参校验；</li><li><strong>能力层</strong>：真正的业务逻辑，只关心业务，不关心谁在调；</li><li><strong>运营层</strong>：开发者注册、AppKey 发放、配额管理、文档门户。</li></ol><p>关键决策：</p><table tabindex="0"><thead><tr><th>决策点</th><th>选择</th><th>理由</th></tr></thead><tbody><tr><td>风格</td><td>REST + JSON</td><td>第三方最容易接，工具链最全</td></tr><tr><td>鉴权</td><td>AppId + 签名 为主，OAuth2 为辅</td><td>服务间对接用签名省事；需要用户授权时才上 OAuth</td></tr><tr><td>限流</td><td>网关层令牌桶，按 AppKey 维度</td><td>业务代码不掺和，配置可热更新</td></tr><tr><td>版本</td><td>URL 路径版本 <code>/v1/</code>，只增不改</td><td>老版本保底可用，新能力走新版本</td></tr><tr><td>文档</td><td>OpenAPI 3.0 生成 + 联调沙箱</td><td>文档即代码，接口变了文档自动跟着变</td></tr></tbody></table><h2 id="关键实现" tabindex="-1">关键实现 <a class="header-anchor" href="#关键实现" aria-label="Permalink to “关键实现”">​</a></h2><p><strong>1. 统一响应结构</strong>——所有对外接口返回同构数据，错误码全局编号：</p><div class="language-json line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;requestId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;req_8f3a2c&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><code>code != 0</code> 一律是业务/系统错误，<code>requestId</code> 打进日志，客户报障时报这个 ID，一分钟能定位到调用记录。</p><p><strong>2. 签名鉴权（AppId + HMAC）</strong>——核心是「参数按序拼接 + 时间戳防重放」：</p><div class="language-java line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">String raw </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> appId </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> timestamp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sortedParams </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> body;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">String sign </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Hex</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HmacSHA256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(raw, appSecret));</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 服务端校验：appId 存在 &amp;&amp; |now - timestamp| &lt;= 5min &amp;&amp; sign 一致</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>时间戳窗口 5 分钟，配合 nonce（随机串）存 Redis 可进一步挡重放。<strong>AppSecret 永远不出服务端</strong>，只给签名用，不进 URL、不进日志。</p><p><strong>3. 限流与配额</strong>：两套东西别混——</p><ul><li><strong>限流</strong>：瞬时速率控制（如 100 QPS），超了直接返回 <code>429</code> + <code>Retry-After</code>，令牌桶在网关做；</li><li><strong>配额</strong>：周期总量控制（如每日 100 万次），按自然日计数，Redis <code>INCR</code> + 过期即可，快到阈值时提前提醒客户。</li></ul><p><strong>4. 版本管理</strong>：<code>/v1/orders</code> 与 <code>/v2/orders</code> 可以同时在线。规则很简单：<strong>老版本只修 bug，不加不删字段；破坏性变更必须开新版本</strong>；废弃走 <code>Deprecation</code> + <code>Sunset</code> 响应头，给足迁移期再下线。</p><p><strong>5. 文档与联调</strong>：接口定义用 OpenAPI 注解写在代码里，构建时生成文档站；再配一个<strong>沙箱环境</strong>（mock 数据 + 自助领测试 AppKey），客户不找人就能跑通第一个请求。</p><h2 id="落地效果-示意" tabindex="-1">落地效果（示意） <a class="header-anchor" href="#落地效果-示意" aria-label="Permalink to “落地效果（示意）”">​</a></h2><ul><li>接入一个新客户的周期，从「拉群、发文档、来回问」缩短到自助注册 + 沙箱自测，人肉答疑量明显下降；</li><li>某客户程序异常打满限流阈值时，只有该 AppKey 被限，其他客户无感知——这是限流按 AppKey 隔离的直接收益；</li><li>老版本 <code>/v1</code> 与新版本 <code>/v2</code> 并行期间，存量客户零改造运行，下线按 Sunset 时间表推进。</li></ul><p>（以上为方案效果示意，非生产统计数据。）</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>对外 API 的工程量，一半在「业务接口」之外：统一规范让客户好接，签名 + 时间戳让调用可追责，限流配额让故障不扩散，版本纪律让老客户不被绑架，文档沙箱让你不用当人肉客服。这五件事在客户只有 1 个时看着多余，到第 10 个客户时就是救命的。</p>`,27)])])}const c=i(e,[["render",p]]);export{g as __pageData,c as default};
